package com.example.riskplatform.service;import com.example.riskplatform.dto.AuthDtos.*;import com.example.riskplatform.security.*;import lombok.RequiredArgsConstructor;import org.springframework.security.authentication.*;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class AuthService{private final AuthenticationManager am;private final JwtUtil jwt;public LoginResponse login(LoginRequest r){Authentication a=am.authenticate(new UsernamePasswordAuthenticationToken(r.getUsername(),r.getPassword()));LoginUser u=(LoginUser)a.getPrincipal();LoginResponse x=new LoginResponse();x.setToken(jwt.generate(u.getUsername()));x.setUserId(u.getUser().getId());x.setUsername(u.getUsername());x.setRealName(u.getUser().getRealName());x.setDeptId(u.getUser().getDeptId());x.setPermissions(u.getPermissions());x.setRoles(u.getRoles());x.setDataScope(u.getDataScope());return x;}}
